const body = $input.first().json.body || {};

const taskId = body.task_id;
const subTaskId = body.sub_task_id;
const setIndex = body.set_index;
const referenceImage = body.reference_image;
const imageType = body.image_type;
const imagePosition = body.image_position;
const callbackSecret = body.callback_secret || '';
const callbackUrl = body.callback_url;

const mainDescription = body.main_description || '';
const detailDescription = body.detail_description || '';

const userPrompt = imageType === 'main' 
  ? mainDescription 
  : detailDescription;


// ============================================================
// 附图提示词库
// 根据 image_position 动态选择
// image_position 范围：2-9
// ============================================================

const subPrompts = {

  2: `
产品场景展示图。
将产品放置在真实生活使用环境中，
突出消费者实际使用场景。
场景符合越南家庭生活习惯，
增强用户代入感和购买欲。
采用商业摄影效果，
保持产品主体真实一致。
`,

  3: `
产品功能展示图。
重点展示产品核心功能和使用方式。
通过视觉表达产品如何解决用户问题。
突出产品价值，
保持产品结构、包装、颜色完全一致。
`,

  4: `
产品卖点展示图。
围绕产品核心优势制作电商宣传视觉。
突出主要卖点，
使用简洁真实的越南语营销文字。
不要夸大效果，
保持产品真实性。
`,

  5: `
产品细节展示图。
展示产品材质、结构、工艺细节。
采用商业微距摄影效果，
提升用户对产品品质的信任。
禁止修改产品细节。
`,

  6: `
产品使用步骤展示图。
展示用户正确使用流程。
通过连续视觉步骤表达操作方式。
画面清晰易懂，
符合越南消费者观看习惯。
`,

  7: `
产品效果对比展示图。
展示使用前后的视觉区别。
突出产品带来的改善效果。
不要生成虚假夸张效果，
保持真实可信。
`,

  8: `
产品生活方式种草图。
模拟越南用户真实生活场景。
展示产品融入日常生活后的便利。
画面具有社交媒体种草感。
`,

  9: `
产品营销转化图。
设计高点击率电商附图。
突出购买理由、优惠信息、赠品信息。
适合 TikTok Shop 越南市场。
增强消费者购买决策。
`
};


// 获取对应位置提示词
const positionPrompt = subPrompts[imagePosition] || subPrompts[2];


// ============================================================
// 基础系统提示词
// ============================================================

const systemPrompt = `
你是一个专业电商产品视觉设计师。

目标市场：越南。

产品视觉要求：

1. 产品必须保持100%一致：
- 产品外观不可改变
- 产品颜色不可改变
- 产品包装不可改变
- 包装上的文字不可修改
- 产品结构不可变形

2. 图片风格：
- 商业电商摄影风格
- 空间立体感
- 广角视觉效果
- 真实高清质感

3. 文字要求：
- 所有卖点文字、营销文案必须使用越南语
- 越南语必须自然真实
- 不出现中文
- 不出现英文营销词

4. 排版要求：
- 避免文字遮挡产品主体
- 不生成白色留白区域

5. 营销限制：
- 不出现具体价格数字
- 可以表达优惠、赠品、限时活动
- 不虚构产品不存在的功能

当前附图设计方向：

${positionPrompt}
`;


// ============================================================
// 最终提示词
// ============================================================

const finalPrompt = systemPrompt;


// ============================================================
// 辅助图片处理
// ============================================================

let auxiliaryImages = [];

try {
  auxiliaryImages = JSON.parse(body.auxiliary_images || '[]');
} catch(e) {
  auxiliaryImages = [];
}


const imagesArray = [
  referenceImage,
  ...auxiliaryImages
].filter(Boolean);


// ============================================================
// 子任务参数
// ============================================================

const subTasks = body.sub_tasks || [];

let currentSubTask = subTasks.find(
  st => st.sub_task_id === subTaskId
) || {};

const styleCode = currentSubTask.style_code || '';


// ============================================================
// 输出
// ============================================================

return {
  taskId,
  subTaskId,
  setIndex,
  referenceImage,
  imageType,
  imagePosition,
  finalPrompt,
  imagesArray,
  styleCode,
  callbackSecret,
  callbackUrl,
  attempts: 0
};

